#include "storage.h"
#include <string.h>
enum{KEY_STATE=100};
static void defaults(AppState*s){memset(s,0,sizeof(*s));s->last_smoked=time(NULL);s->cigarettes_per_day=20;s->money_cents_per_day=300;s->currency=CUR_USD;}
void storage_load(AppState*s){defaults(s);if(persist_exists(KEY_STATE)&&persist_get_size(KEY_STATE)==sizeof(*s))persist_read_data(KEY_STATE,s,sizeof(*s));if(s->cigarettes_per_day<1||s->cigarettes_per_day>100)s->cigarettes_per_day=20;if(s->money_cents_per_day<0||s->money_cents_per_day>50000)s->money_cents_per_day=300;if(s->currency<CUR_USD||s->currency>CUR_RUB)s->currency=CUR_USD;}
void storage_save(const AppState*s){persist_write_data(KEY_STATE,s,sizeof(*s));}
void storage_record_relapse(AppState*s,time_t now){time_t e=now>s->last_smoked?now-s->last_smoked:0;if(e>s->best_streak)s->best_streak=e;int32_t av=(int32_t)(((int64_t)e*s->cigarettes_per_day)/86400),sv=(int32_t)(((int64_t)e*s->money_cents_per_day)/86400);s->lifetime_avoided_milli+=(int32_t)(((int64_t)e*s->cigarettes_per_day*1000)/86400);s->lifetime_saved_cents_milli+=(int32_t)(((int64_t)e*s->money_cents_per_day*1000)/86400);AttemptRecord*r=&s->history[s->history_head];r->start=(int32_t)s->last_smoked;r->end=(int32_t)now;r->duration=(int32_t)e;r->avoided=av;r->saved_cents=sv;s->history_head=(s->history_head+1)%HISTORY_MAX;if(s->history_count<HISTORY_MAX)s->history_count++;s->attempts++;s->last_smoked=now;s->notified_mask=0;storage_save(s);}
void storage_reset(AppState*s){Currency c=s->currency;int cpd=s->cigarettes_per_day,m=s->money_cents_per_day;defaults(s);s->currency=c;s->cigarettes_per_day=cpd;s->money_cents_per_day=m;s->configured=true;storage_save(s);}
